// $input.all() = righe Google Sheets con gli ID già processati
// $('Recupera Newsletter Normative').all() = email Gmail recuperate

var sheetsRows = $input.all();
var processedIds = new Set(
  sheetsRows
    .map(function(row) { return (row.json.messageId || '').toString(); })
    .filter(function(id) { return id !== ''; })
);

var emails = $('Recupera Newsletter Normative').all();
var nuove = emails.filter(function(email) {
  var id = (email.json.id || '').toString();
  return id !== '' && !processedIds.has(id);
});

// Se non ci sono email nuove, il workflow si ferma qui senza errori
return nuove.map(function(email) {
  return { json: email.json };
});

var items = $input.all();
return items.map(function(item) {
  var d = item.json;
  var from = '';
  try { from = d.from.value[0].address; } catch(e) { from = d.from || ''; }

  // FIX: fallback HTML se plain text è assente
  var body = d.text || '';
  if (!body && d.html) {
    body = d.html
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<script[\s\S]*?<\/script>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/\s+/g, ' ')
      .trim();
  }
  if (!body) body = d.snippet || '';

  return { json: {
    messageId: d.id || '',
    sourceSubject: d.subject || '',
    sourceFrom: from,
    sourceBody: body.substring(0, 6000)
  } };
});

var items = $input.all();
var output = [];
items.forEach(function(item, idx) {
  var raw = item.json.text || '';
  var arr = [];
  try {
    var cleaned = raw.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
    var m = cleaned.match(/\[[\s\S]*\]/);
    if (m) arr = JSON.parse(m[0]);
  } catch (e) {}
  arr.forEach(function(u) {
    output.push({
      json: {
        title: u.title || 'Aggiornamento normativo',
        summary: u.summary || '',
        sourceSubject: u.sourceSubject || '',
        sourceFrom: u.sourceFrom || ''
      },
      pairedItem: { item: idx }
    });
  });
});
return output;

var input = $input.item.json;
var content = '';
var citations = [];
try {
  content = (input.choices && input.choices[0] && input.choices[0].message && input.choices[0].message.content) || '';
  citations = input.citations || [];
} catch (e) {}

var update = {};
try { update = $('Estrai Lista Update').item.json; } catch (e) {}

var lines = [];
lines.push('### ' + (update.title || 'Aggiornamento'));
lines.push('');
lines.push(update.summary || '');
lines.push('');
lines.push('**Fonte newsletter:** ' + (update.sourceSubject || '') + ' (' + (update.sourceFrom || '') + ')');
lines.push('');
lines.push('**Ricerca normativa:**');
lines.push(content || 'Nessun riferimento normativo specifico trovato.');
if (citations.length > 0) {
  lines.push('');
  lines.push('**Link ai documenti:**');
  citations.forEach(function (c, i) { lines.push((i + 1) + '. ' + c); });
}

return { json: { block: lines.join('\n') } };

var item = $input.first().json;
var blocks = item.block || [];
var dateStr = new Date().toLocaleDateString('it-IT');
var lines = [];
lines.push('AGGIORNAMENTO NORMATIVO LAVORO');
lines.push('Studio Assirelli - Consulenza del Lavoro');
lines.push('Data: ' + dateStr);
lines.push('Numero aggiornamenti: ' + blocks.length);
lines.push('');
lines.push('========================================');
lines.push('');
lines.push(blocks.length > 0 ? blocks.join('\n\n---\n\n') : 'Nessun aggiornamento normativo rilevato oggi.');

return [{ json: {
  docTitle: 'Aggiornamento Normativo Lavoro - ' + dateStr,
  documentText: lines.join('\n'),
  updateCount: blocks.length
} }];

