var compilato = $('Compila Documento Finale').first().json;
var studio = '';
try { studio = $('Elabora Studio Claude').first().json.studioClaudeText || ''; } catch(e) {}
var docUrl = '';
try { docUrl = $('Crea Documento Aggiornamento').first().json.webViewLink || ''; } catch(e) {}

var dataStr = new Date().toISOString().split('T')[0];
var docTitle = compilato.docTitle || ('Aggiornamento Normativo Lavoro - ' + dataStr);
var updateCount = compilato.updateCount || 0;

var markdown = '---\n' +
'data: "' + dataStr + '"\n' +
'fonte: "Aggregato multi-fonte (Teleconsul, Dottrina Lavoro, Wolters Kluwer, FAP ACLI, Fisco e Tasse, Ateneoweb)"\n' +
'materia: "Lavoro"\n' +
'tipo_atto: "Altro"\n' +
'priorita: "Media"\n' +
'numero_aggiornamenti: ' + updateCount + '\n' +
'tags:\n' +
'  - "#aggiornamento_normativo"\n' +
'  - "#teleconsul"\n' +
'---\n' +
'# ' + docTitle + '\n\n' +
'> [!INFO] Riepilogo giornaliero\n' +
'> **Aggiornamenti rilevati:** ' + updateCount + ' | **Data:** ' + dataStr + '\n\n' +
'## 📰 Studio Completo (Claude)\n\n' +
studio + '\n\n' +
'---\n\n' +
'## 📋 Testo Aggregato Newsletter\n\n' +
(compilato.documentText || 'Nessun contenuto.') + '\n\n' +
'---\n\n' +
'## 📎 Riferimenti\n\n' +
'- **Google Doc:** ' + (docUrl ? '[Apri su Drive](' + docUrl + ')' : 'Non disponibile') + '\n';

var filename = dataStr + ' - Aggiornamento Normativo Lavoro (Teleconsul).md';

return [{
  json: { fileName: filename },
  binary: {
    data: {
      data: Buffer.from(markdown, 'utf-8').toString('base64'),
      mimeType: 'text/markdown',
      fileName: filename
    }
  }
}];
